contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 amount) public payable {
        require(to != address(0));

        uint256 balFrom_before = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balTo_before = c.balanceOf(to); if (__ESBMC_reverted()) return;

        bool reverted;
        bool ok = c.transfer(to, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balFrom_after = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 balTo_after = c.balanceOf(to); if (__ESBMC_reverted()) return;

        assert(reverted || (balFrom_after + balTo_after == balFrom_before + balTo_before));
    }

    receive() external payable { }
}

