pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ERCDDAToken c;

    function setUp() public {
        c = new ERCDDAToken(0, "", "");
    }

    function _run(address to, uint256 amount) internal {
        vm.assume(to != address(0));
        uint256 balFrom_before;
        try c.balanceOf(address(this)) returns (uint256 __r) { balFrom_before = __r; } catch { return; }
        uint256 balTo_before;
        try c.balanceOf(to) returns (uint256 __r) { balTo_before = __r; } catch { return; }
        bool reverted;
        try c.transfer(to, amount) returns (bool ok) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balFrom_after;
        try c.balanceOf(address(this)) returns (uint256 __r) { balFrom_after = __r; } catch { return; }
        uint256 balTo_after;
        try c.balanceOf(to) returns (uint256 __r) { balTo_after = __r; } catch { return; }
        assertTrue(reverted || (balFrom_after + balTo_after == balFrom_before + balTo_before));
    }

    function testFuzz_run(address to, uint256 amount) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, amount);
    }

    receive() external payable { }
}
